"""Brand assets are composited from pinned originals, never regenerated by a prompt.

Planar samples are explicit, reviewed canvas-space observations of a fixed local
plate. This module neither estimates motion nor promises model-side identity.
"""
from PIL import Image, ImageChops
from .store import fingerprint


def target_binding(project, layer):
    asset = next(a for a in project.assets if a.id == layer.asset)
    return fingerprint(dict(asset=asset.sha256, layer=layer.model_dump(mode='json'),
                            width=project.width, height=project.height,
                            fps=project.fps.model_dump(), frames=project.frames))


def validate_quad(quad, width, height):
    if quad is None:
        raise ValueError('BRAND_ANCHOR: visible frame requires four corners')
    if any(not 0 <= x <= width or not 0 <= y <= height for x, y in quad):
        raise ValueError('BRAND_ANCHOR: corners must stay inside the canvas')
    for i in range(4):
        a, b, c = quad[i], quad[(i+1) % 4], quad[(i+2) % 4]
        cross = (b[0]-a[0])*(c[1]-b[1]) - (b[1]-a[1])*(c[0]-b[0])
        if cross < 1:
            raise ValueError('BRAND_ANCHOR: degenerate, mirrored or non-convex quad')


def validate_project(project):
    assets = {a.id: a for a in project.assets}
    layers = {l.id: l for l in project.layers}
    for layer in project.layers:
        lock = layer.brand_lock
        if lock is None:
            continue
        source = assets.get(layer.asset)
        if layer.kind != 'image' or source is None or source.kind != 'image':
            raise ValueError('BRAND_LOCK: requires an imported original image, not a generated task')
        if source.sha256 != lock.source_sha256:
            raise ValueError('BRAND_LOCK: source hash changed; review and rebind the asset')
        if (layer.crop or layer.fit != 'contain' or layer.keyframes or layer.rotation or
                layer.scale != 1 or layer.opacity != 1 or layer.fade_in or layer.fade_out):
            raise ValueError('BRAND_LOCK: crop, stretch, effects and animated transforms are forbidden')
        if any(layer.id in (t.source, t.target) for t in project.transitions):
            raise ValueError('BRAND_LOCK: transitions cannot modify a protected layer')
        if lock.mode == 'screen':
            if lock.target_layer or lock.target_binding or lock.samples or lock.mask_hashes or lock.occlusion != 'none':
                raise ValueError('BRAND_LOCK: screen placement cannot contain planar data')
            if not (0 <= layer.x <= project.width-layer.width and 0 <= layer.y <= project.height-layer.height):
                raise ValueError('BRAND_LOCK: screen placement is clipped')
            continue
        target = layers.get(lock.target_layer)
        if (target is None or target.id == layer.id or target.brand_lock or
                target.kind not in ('image', 'video') or target.asset not in assets):
            raise ValueError('BRAND_ANCHOR: target must be a frozen local image/video layer')
        if not target.start <= layer.start < layer.end <= target.end or layer.track <= target.track:
            raise ValueError('BRAND_ANCHOR: overlay must be above and within target interval')
        if any(target.id in (t.source, t.target) for t in project.transitions):
            raise ValueError('BRAND_ANCHOR: bake target transitions before reviewing coordinates')
        if target_binding(project, target) != lock.target_binding:
            raise ValueError('BRAND_ANCHOR: target or timeline changed; review all samples again')
        if layer.x or layer.y:
            raise ValueError('BRAND_ANCHOR: corners are canvas-space; x/y must be zero')
        if len(lock.samples) != layer.end-layer.start or any(s.frame != layer.start+i for i, s in enumerate(lock.samples)):
            raise ValueError('BRAND_ANCHOR: one ordered sample per frame required; no interpolation across gaps')
        used_masks = set()
        for sample in lock.samples:
            if not sample.visible:
                if sample.quad is not None or sample.mask_asset is not None:
                    raise ValueError('BRAND_ANCHOR: hidden samples must omit geometry and mask')
                continue
            validate_quad(sample.quad, project.width, project.height)
            if lock.occlusion == 'none':
                if sample.mask_asset:
                    raise ValueError('BRAND_ANCHOR: choose per_frame_mask for occlusion')
            else:
                mask = assets.get(sample.mask_asset)
                if mask is None or mask.kind != 'image' or lock.mask_hashes.get(mask.id) != mask.sha256:
                    raise ValueError('BRAND_ANCHOR: every visible frame needs a pinned visibility mask')
                used_masks.add(mask.id)
        if set(lock.mask_hashes) != used_masks:
            raise ValueError('BRAND_ANCHOR: mask identities must exactly match samples')
    for task in project.tasks:
        reference = task.brand_reference
        if reference is None:
            continue
        if task.kind != 'generation' or task.output_kind != 'video':
            raise ValueError('BRAND_REFERENCE: only video generation supports this policy')
        if len(set(task.inputs)) != len(task.inputs) or len(task.input_roles) != len(task.inputs):
            raise ValueError('BRAND_REFERENCE: unique inputs and explicit roles required')
        roles = dict(zip(task.inputs, task.input_roles))
        if reference.mode == 'video_edit':
            videos = [aid for aid, role in roles.items() if role == 'reference_video']
            if (len(videos) != 1 or videos[0] not in assets or assets[videos[0]].kind != 'video' or
                    any(r in ('first_frame', 'last_frame') for r in task.input_roles) or
                    roles.get(reference.anchor_asset) != 'reference_image' or
                    reference.camera != 'preserve_reference'):
                raise ValueError('BRAND_REFERENCE: video_edit needs one local reference video, image anchor, no first/last frame and preserve_reference camera')
        elif (roles.get(reference.anchor_asset) != 'first_frame' or task.input_roles.count('first_frame') != 1 or
                reference.camera == 'preserve_reference' or 'reference_video' in task.input_roles):
            raise ValueError('BRAND_REFERENCE: exactly one approved first-frame anchor required; reference-video editing uses video_edit')
        for aid in [reference.anchor_asset, *reference.identity_assets]:
            if aid not in assets or assets[aid].kind != 'image' or roles.get(aid) not in ('first_frame', 'reference_image'):
                raise ValueError('BRAND_REFERENCE: approved local images must be mapped to first_frame/reference_image')


def generation_prompt(task):
    prompt = task.get('prompt') or ''
    reference = task.get('brand_reference')
    if not reference:
        return prompt
    attachment = (
        'Preserve the artwork in the local coordinates of its physical supporting surface, not in screen coordinates. '
        'The mark must inherit that specific part\'s translation, rotation, perspective, occlusion and natural motion blur. '
        'For a mark attached to a rotating wheel or hub, rotate it with that wheel or hub at the same angular direction, speed and phase; '
        'do not stabilize it upright relative to the camera or car body, unless the brief explicitly specifies a self-leveling hubcap. '
        'Preserve the design and spelling without morphing strokes; preserving artwork does not mean freezing its orientation. '
    )
    if reference.get('mode') == 'video_edit':
        return prompt + '\n\nBrand reference direction (visual guidance): Preserve the reference video camera motion, edits, shot timing and action. ' + \
            'Use the approved image anchor and identity close-ups to preserve the replacement product silhouette, proportions, label layout, spelling, colors and material. ' + \
            attachment + \
            'Do not add a floating screen logo or change the source choreography to display a logo.'
    camera = 'Keep the camera locked.' if reference['camera'] == 'locked' else 'Use only a gentle camera move with small parallax.'
    return prompt + '\n\nBrand reference direction (visual guidance): Use the supplied first frame as the composition anchor. ' + \
        'Preserve the reference product silhouette, proportions, label layout, spelling, colors and material. ' + \
        attachment + camera + ' Camera locking does not freeze moving product parts. '


def perspective_coefficients(quad, width, height):
    """Solve the inverse homography used by Pillow, with partial-pivot elimination."""
    rows = []
    for (x, y), (u, v) in zip(quad, ((0, 0), (width, 0), (width, height), (0, height))):
        rows.append([x, y, 1, 0, 0, 0, -u*x, -u*y, u])
        rows.append([0, 0, 0, x, y, 1, -v*x, -v*y, v])
    for col in range(8):
        pivot = max(range(col, 8), key=lambda i: abs(rows[i][col]))
        rows[col], rows[pivot] = rows[pivot], rows[col]
        value = rows[col][col]
        if abs(value) < 1e-10:
            raise ValueError('BRAND_ANCHOR: unstable perspective transform')
        rows[col] = [v/value for v in rows[col]]
        for i in range(8):
            if i != col:
                factor = rows[i][col]
                rows[i] = [a-factor*b for a, b in zip(rows[i], rows[col])]
    # Exact translations/scales should not acquire one-LSB interpolation noise
    # merely from elimination roundoff (the original image is sampled anew).
    return tuple(round(row[-1]) if abs(row[-1]-round(row[-1])) < 1e-12 else row[-1] for row in rows)


def planar_image(raster, layer, frame):
    sample = layer.brand_lock.samples[frame-layer.start]
    size = (raster.p.width, raster.p.height)
    if not sample.visible:
        return Image.new('RGBA', size)
    original = raster.images[layer.asset]
    coeff = perspective_coefficients(sample.quad, original.width, original.height)
    image = original.transform(size, Image.Transform.PERSPECTIVE, coeff, Image.Resampling.BICUBIC)
    if sample.mask_asset:
        source_mask = raster.images[sample.mask_asset]
        mask = ImageChops.multiply(source_mask.convert('L'), source_mask.getchannel('A'))
        if mask.size != size:
            raise ValueError('BRAND_ANCHOR: visibility mask must match canvas dimensions')
        image.putalpha(ImageChops.multiply(image.getchannel('A'), mask))
    return image


def preflight(project):
    protected = [dict(layer=l.id, mode=l.brand_lock.mode, sourceSha256=l.brand_lock.source_sha256,
                      frames=l.end-l.start, targetBinding=l.brand_lock.target_binding,
                      geometry='fixed' if l.brand_lock.mode == 'screen' else 'explicit-per-frame',
                      review='caller-declared; not an automated quality measurement')
                 for l in project.layers if l.brand_lock]
    references = [t.id for t in project.tasks if t.brand_reference]
    return dict(protectedLayers=protected, referenceGuidedTasks=references, reviewRequired=project.brand_review_required or bool(protected or references),
                modelIdentityGuaranteed=False, automaticTracking=False,
                limitations=['Reference prompts do not enforce model-side geometry.',
                             'Planar mapping requires accurate reviewed coordinates/masks; curved or deforming surfaces need another method.',
                             'A transparent logo does not erase an already deformed label beneath it; use a clean plate or a full opaque label patch.',
                             'Resampling and lossy video encoding can change pixels; output-frame visual review is still required.'])


def bind(engine, args):
    """Bind source/plate/mask hashes into an immutable revision; retries stay idempotent."""
    from .schema import Project, BrandPlacement
    placement = BrandPlacement.model_validate(args['placement'])
    stored = engine.store.project(args['projectId'], args['baseRevision'])
    project = Project.model_validate(stored['document'])
    layer = next((l for l in project.layers if l.id == args['layerId']), None)
    if layer is None:
        raise ValueError('BRAND_LOCK: layer not found')
    assets = {a.id: a for a in project.assets}
    if layer.asset not in assets:
        raise ValueError('BRAND_LOCK: import the original asset first')
    value = placement.model_dump(mode='json')
    value['source_sha256'] = assets[layer.asset].sha256
    if placement.mode == 'planar':
        target = next((l for l in project.layers if l.id == placement.target_layer), None)
        if target is None or target.asset not in assets:
            raise ValueError('BRAND_ANCHOR: import the completed plate first')
        value['target_binding'] = target_binding(project, target)
        masks = {s.mask_asset for s in placement.samples if s.mask_asset}
        if masks - assets.keys():
            raise ValueError('BRAND_ANCHOR: mask asset missing')
        value['mask_hashes'] = {aid: assets[aid].sha256 for aid in masks}
    document = project.model_dump(mode='json')
    next(l for l in document['layers'] if l['id'] == layer.id)['brand_lock'] = value
    return engine.edit(dict(commandId=args['commandId'], projectId=args['projectId'],
                            baseRevision=args['baseRevision'], document=document))


def requires_review(spec):
    return spec.get('brand_review_required', False) or any(l.get('brand_lock') for l in spec['layers']) or any(t.get('brand_reference') for t in spec['tasks'])


def review_build(engine, args):
    from pathlib import Path
    from .render import sha
    def record(db):
        build = engine.store.build(args['buildId'], db)
        if build['status'] != 'succeeded' or not requires_review(build['spec']):
            raise ValueError('BRAND_REVIEW: requires a successful brand-aware build')
        result = build['result']
        if args['sha256'] != result['sha256'] or not Path(result['path']).is_file() or sha(result['path']) != args['sha256']:
            raise ValueError('BRAND_REVIEW: output identity changed')
        if not args['note'].strip() or len(args['note']) > 4000:
            raise ValueError('BRAND_REVIEW: record the inspected frames and findings')
        db.execute('INSERT OR REPLACE INTO brand_reviews VALUES(?,?,?,?)',
                   (build['id'], args['sha256'], int(args['approved']), args['note']))
        return dict(buildId=build['id'], sha256=args['sha256'], approved=args['approved'],
                    method='caller visual review; not automatic verification', note=args['note'])
    return engine.store.mutate(args['commandId'], dict(op='review_brand_build', **args), record)
